let systemFormat = undefined;

/**
 * @todo Consider removing lazy initialization, since it's not clear if provides any noticeable benefit.
 */
function ensureModuleLoaded() {
    if (!systemFormat) {
        systemFormat = require("../build/Release/systemFormat.node");
    }
}

function getListSeparator() {
    try {
        ensureModuleLoaded();
        return systemFormat.getListSeparator();
    } catch (error) {
        console.error(error);
        return ",";
    }
}

function formatNumber(number, precision) {
    try {
        ensureModuleLoaded();

        /**
         * Windows API limits precision to 0-9 digits
          * @see https://learn.microsoft.com/en-us/windows/win32/api/winnls/ns-winnls-numberfmtw
         */
        const clampedPrecision = Math.min(Math.max(Math.floor(precision), 0), 9);
        return systemFormat.formatNumber(number, clampedPrecision);
    } catch (error) {
        console.error(error);
        return number.toLocaleString();
    }
}

function formatDateTime(formatter, fallbackFormatter, dateTime, length) {
    try {
        ensureModuleLoaded();

        let lengthInt;
        switch (length) {
            case "full": lengthInt = 4; break;
            case "long": lengthInt = 3; break;
            case "medium": lengthInt = 2; break;
            default: lengthInt = 1;
        }

        return formatter(systemFormat, dateTime.getTime(), lengthInt);
    } catch (error) {
        console.error(error);
        return fallbackFormatter(dateTime);
    }
}

const defaultBytesPrecision = 2;
const sizeUnits = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"];
function formatBytes(bytes, precision) {
    if (bytes === undefined) {
        bytes = 0.0;
    }

    const divisor = 1024;

    let index = 0;
    while (bytes >= divisor && index < sizeUnits.length - 1) {
        bytes /= divisor;
        index++;
    }

    const precisionToUse = index === 0 ? 0 : (precision ?? defaultBytesPrecision);

    return `${formatNumber(bytes, precisionToUse)} ${sizeUnits[index]}`;
}

module.exports.getListSeparator = () => getListSeparator();

module.exports.formatNumber = (number, precision) => formatNumber(number, precision);

module.exports.formatLocalDate = (dateTime, length) => formatDateTime(
    (systemFormat, unixTime, length) => systemFormat.formatLocalDate(unixTime, length),
    (dateTime) => dateTime.toLocaleDateString(),
    dateTime,
    length
);

module.exports.formatLocalTime = (dateTime, length) => formatDateTime(
    (systemFormat, unixTime, length) => systemFormat.formatLocalTime(unixTime, length),
    (dateTime) => dateTime.toLocaleTimeString(),
    dateTime,
    length
);

module.exports.formatLocalDateTime = (dateTime, length) => formatDateTime(
    (systemFormat, unixTime, length) => systemFormat.formatLocalDateTime(unixTime, length),
    (dateTime) => dateTime.toLocaleString(),
    dateTime,
    length
);

module.exports.formatUtcDate = (dateTime, length) => formatDateTime(
    (systemFormat, unixTime, length) => systemFormat.formatUtcDate(unixTime, length),
    (dateTime) => dateTime.toUTCString(),
    dateTime,
    length
);

module.exports.formatUtcTime = (dateTime, length) => formatDateTime(
    (systemFormat, unixTime, length) => systemFormat.formatUtcTime(unixTime, length),
    (dateTime) => dateTime.toUTCString(),
    dateTime,
    length
);

module.exports.formatUtcDateTime = (dateTime, length) => formatDateTime(
    (systemFormat, unixTime, length) => systemFormat.formatUtcDateTime(unixTime, length),
    (dateTime) => dateTime.toUTCString(),
    dateTime,
    length
);

module.exports.formatBytes = (size, precision) => formatBytes(size, precision);
